import cv2from collections import defaultdictdef tracking(frame, model, ):    results = model.track(        frame,        persist=True,        tracker="bytetrack.yaml",        imgsz=1280,        classes=[2],        conf=0.25,        verbose=False,    )[0]    # print(results.boxes)    for result in results:        box = result.boxes.data.tolist()[0]        xmin, ymin, xmax, ymax, class_id, confidence = box[:6]        x = int(xmin)        y = int(ymin)        width = int(xmax - xmin)        height = int(ymax - ymin)        class_id = int(class_id)        cen_car = ((xmin + xmax) / 2, ymin)        cv2.rectangle(frame, (x, y), (x + width, y + height), (0, 255, 0), 2)        cv2.putText(frame, str(class_id), (x, y), cv2.FONT_HERSHEY_SIMPLEX, 2, (0, 0, 255), 2)